import { ethers } from "ethers";

// The contract address from our local deployment
export const CONTRACT_ADDRESS = "0xbDd0Db1246E4262fcF29569b691B3868d804B726";

// The ABI generated by Solidity compiler for EligibilityLogger
export const CONTRACT_ABI = [
  "function logAssessment(string _caseId, string _dataSources, string _reasoningChain, uint8 _confidenceLevel, string _paralegalResponse)",
  "function getLogCount(string _caseId) view returns (uint256)",
  "function getLog(string _caseId, uint256 index) view returns (string, string, uint8, string, uint256, address)",
  "event LogCreated(string indexed caseId, uint8 confidenceLevel, string paralegalResponse, uint256 timestamp)"
];

/**
 * Interface representing a returned log from the blockchain.
 */
export interface BlockchainLog {
  dataSources: string;
  reasoningChain: string;
  confidenceLevel: number;
  paralegalResponse: string;
  timestamp: string;
  loggedBy: string;
}

/**
 * Helper to ensure the browser has a Web3 injected provider (like MetaMask).
 */
export async function getProvider() {
  if (typeof window === "undefined" || !(window as any).ethereum) {
    throw new Error("No crypto wallet found. Please install MetaMask.");
  }
  
  // Request account connection if not already authorized
  await (window as any).ethereum.request({ method: "eth_requestAccounts" });
  return new ethers.BrowserProvider((window as any).ethereum);
}

/**
 * Writes an immutable assessment log to the smart contract via MetaMask.
 */
export async function submitLogToBlockchain(
  caseId: string,
  dataSources: string,
  reasoningChain: string,
  confidenceLevel: number,
  paralegalResponse: string
): Promise<{ hash: string; receipt: any }> {
  const provider = await getProvider();
  const signer = await provider.getSigner();

  const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, signer);

  console.log(`Submitting log for case: ${caseId}...`);
  const tx = await contract.logAssessment(
    caseId,
    dataSources,
    reasoningChain,
    confidenceLevel,
    paralegalResponse
  );

  console.log("Transaction sent. Waiting for confirmation...");
  const receipt = await tx.wait(); // Wait for the miners

  return { hash: tx.hash, receipt };
}

/**
 * Retrieves the most recent log for a given case from the blockchain.
 */
export async function fetchLatestLog(caseId: string): Promise<BlockchainLog | null> {
  try {
    const provider = await getProvider();
    
    // We don't need a signer to read data securely
    const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, provider);

    const logCountBigInt = await contract.getLogCount(caseId);
    const logCount = Number(logCountBigInt);

    if (logCount === 0) return null; // No logs yet

    // Array is 0-indexed, fetch the latest one
    const recentIndex = logCount - 1;
    const logResult = await contract.getLog(caseId, recentIndex);

    // Decode tuple: (dataSources, reasoning, confidence, paralegalResponse, timestamp, loggedBy)
    const rawTimestamp = Number(logResult[4]);
    const displayTime = rawTimestamp > 0 
      ? new Date(rawTimestamp * 1000).toLocaleString('en-IN') 
      : "Unknown";

    return {
      dataSources: logResult[0],
      reasoningChain: logResult[1],
      confidenceLevel: Number(logResult[2]),
      paralegalResponse: logResult[3],
      timestamp: displayTime,
      loggedBy: logResult[5],
    };
  } catch (error) {
    console.error("Error fetching logs:", error);
    return null;
  }
}
